# Extract full code for each code cell and check for referenced data files
import re, os, textwrap

code_cells = []
for i, cell in enumerate(nb.get("cells", [])):
    if cell.get("cell_type") == "code":
        src = "".join(cell.get("source", []))
        code_cells.append((i, src))

# Detect csv filenames referenced
csvs = set()
for idx, src in code_cells:
    for m in re.finditer(r"read_csv\(\s*['\"]([^'\"]+)['\"]\s*\)", src):
        csvs.add(m.group(1))

csv_status = {name: os.path.exists(os.path.join("/mnt/data", name)) for name in csvs}

print("CSV files referenced and whether they exist in /mnt/data:")
for name, exists in csv_status.items():
    print(f"- {name}: {'FOUND' if exists else 'MISSING'}")

# Also dump the code cells for reference (truncated to avoid flooding)
for idx, src in code_cells:
    header = f"\n--- Cell {idx} ---"
    print(header)
    print(textwrap.shorten(src.replace("\n", " "), width=400, placeholder=" ..."))
